public record ApiErrorResponse(
    String errorCode,
    String message,
    String path,
    Instant timestamp,
    Map<String, String> validationErrors
) {
    public static ApiErrorResponse of(String code, String message, String path) {
        return new ApiErrorResponse(code, message, path, Instant.now(), Collections.emptyMap());
    }
}

@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(DomainValidationException.class)
    public ResponseEntity<ApiErrorResponse> handleDomainValidation(DomainValidationException ex, WebRequest request) {
        ApiErrorResponse response = new ApiErrorResponse(
            "ERR_DOMAIN_VALIDATION",
            ex.getMessage(),
            request.getDescription(false).replace("uri=", ""),
            Instant.now(),
            ex.getValidationErrors()
        );
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(response);
    }
}
